#!/usr/bin/env python3
import sys

BASE36_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def to_base36(n: int) -> str:
    """Convert an integer to a base36 string."""
    if n == 0:
        return "0"
    chars = []
    while n > 0:
        n, r = divmod(n, 36)
        chars.append(BASE36_ALPHABET[r])
    return "".join(reversed(chars))

def main():
    try:
        with open("ids.txt", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("ORD-0001")
        return

    # Find the last non-empty line
    last_id = None
    for line in reversed(lines):
        stripped = line.strip()
        if stripped:
            last_id = stripped
            break

    if last_id is None:
        print("ORD-0001")
        return

    # Extract the 4-character suffix after "ORD-"
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Error: unexpected id format: {last_id}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    try:
        num = int(suffix, 36)
    except ValueError:
        print(f"Error: invalid base36 suffix: {suffix}", file=sys.stderr)
        sys.exit(1)

    next_num = num + 1
    next_suffix = to_base36(next_num).zfill(4).upper()
    print(f"ORD-{next_suffix}")

if __name__ == "__main__":
    main()
