#!/usr/bin/env python3
"""Read ids.txt and print the next order id to stdout."""

import pathlib

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert a non-negative integer to a zero-padded 4-character base-36 string."""
    digits = []
    for _ in range(4):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a 4-character base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def main() -> None:
    txt = pathlib.Path("ids.txt")
    ids = txt.read_text().strip().splitlines()

    if not ids:
        next_id = to_base36(0)
    else:
        last = ids[-1].strip()
        if not last:
            next_id = to_base36(0)
        else:
            suffix = last.removeprefix("ORD-") if last.startswith("ORD-") else last
            next_id = to_base36(from_base36(suffix) + 1)

    print(f"ORD-{next_id}")


if __name__ == "__main__":
    main()

