import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base-36 string of the given width."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def next_id(path: str = "ids.txt") -> str:
    with open(path) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        return "ORD-0000"

    last = lines[-1]
    suffix = last[4:]  # everything after "ORD-"
    val = int(suffix, 36) + 1
    return f"ORD-{to_base36(val, 4)}"


if __name__ == "__main__":
    print(next_id())

