#!/usr/bin/env python3
"""Read attendees.txt (UTF-8, one name per line) and write roster.txt (UTF-8)
with the same names sorted alphabetically."""

from pathlib import Path


def main() -> None:
    input_path = Path("attendees.txt")
    output_path = Path("roster.txt")

    # Read names, strip whitespace, skip empty lines
    names = [
        line.strip()
        for line in input_path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]

    # Sort alphabetically (case-insensitive)
    names.sort(key=str.casefold)

    # Write roster.txt
    output_path.write_text("\n".join(names) + "\n", encoding="utf-8")

    print(f"Wrote {len(names)} names to {output_path}")


if __name__ == "__main__":
    main()

