#!/usr/bin/env python3
"""Build manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
import os
import sys

RELEASE_DIR = "release"
MANIFEST_PATH = "manifest.json"


def sha256_digest(filepath: str) -> str:
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def main() -> None:
    root = os.path.abspath(os.path.dirname(__file__))
    release_root = os.path.join(root, RELEASE_DIR)

    if not os.path.isdir(release_root):
        print(f"Error: {RELEASE_DIR}/ directory not found.", file=sys.stderr)
        sys.exit(1)

    manifest = {}

    for dirpath, _dirnames, filenames in os.walk(release_root):
        for filename in filenames:
            abs_path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(abs_path, root)
            manifest[rel_path] = sha256_digest(abs_path)

    manifest_path = os.path.join(root, MANIFEST_PATH)
    with open(manifest_path, "w") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")

    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

