"""List files under reports/ in report order (sorted by numeric suffix)."""

import os
import re

REPORTS_DIR = "reports"

def report_sort_key(filename):
    """Extract the numeric part from report-N.txt for sorting."""
    match = re.search(r"report-(\d+)", filename)
    return int(match.group(1)) if match else float("inf")

def main():
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"Error: '{REPORTS_DIR}' directory not found.")
        return

    # Filter for report-<n>.txt files and sort by number
    report_files = [f for f in files if re.match(r"report-\d+\.txt", f)]
    report_files.sort(key=report_sort_key)

    for f in report_files:
        print(f)

if __name__ == "__main__":
    main()

