"""Print report file names under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_sort_key(filename: str) -> int:
    """Extract the integer n from report-N.txt for numeric sorting."""
    m = re.match(r"report-(\d+)\.txt$", filename)
    if m is None:
        return float("inf")  # non-conforming files go last
    return int(m.group(1))


