    except FileNotFoundError:
        return  # no reports yet, nothing to print

    report_files = [e for e in entries if re.match(r"report-\d+\.txt$", e)]
    report_files.sort(key=report_sort_key)

    for fname in report_files:
        print(fname)


if __name__ == "__main__":
    main()

