"""Count word frequencies in all .txt files under docs/."""

import glob
from collections import Counter

PUNCTUATION = ".,;:!?"
DOCS_PATTERN = "docs/**/*.txt"
OUTPUT = "counts.txt"


def strip_punctuation(word: str) -> str:
    """Strip punctuation characters . , ; : ! ? from word edges."""
    return word.strip(PUNCTUATION)


def main() -> None:
    counter: Counter[str] = Counter()

    for path in sorted(glob.glob(DOCS_PATTERN, recursive=True)):
        with open(path, encoding="utf-8") as f:
            for line in f:
                for raw in line.split():
                    word = strip_punctuation(raw.lower())
                    if word:
                        counter[word] += 1

    with open(OUTPUT, "w", encoding="utf-8") as f:
        for word in sorted(counter):
            f.write(f"{word} {counter[word]}\n")

    print(f"Wrote {len(counter)} unique words to {OUTPUT}")


if __name__ == "__main__":
    main()

