Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line in app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message.
Entries strictly older than 7 days before AS_OF are appended to archive.log,
and app.log is rewritten with the remaining entries (order preserved).
"""

import sys
from datetime import datetime, timezone

APP_LOG = "app.log"
ARCHIVE_LOG = "archive.log"


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse a YYYY-MM-DD HH:MM:SS prefix from the line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
